nt", "cited_by_count": 0, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2508.20315", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2508.20315", "doi": null, "is_oa": true, "landing_page_url": "http://arxiv.org/abs/2508.20315", "pdf_url": "https://arxiv.org/pdf/2508.20315", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "The growing complexity of urban mobility and the demand for efficient, sustainable, and adaptive solutions have positioned Intelligent Transportation Systems (ITS) at the forefront of modern infrastructure innovation. At the core of ITS lies the challenge of autonomous decision-making across dynamic, large scale, and uncertain environments where multiple agents traffic signals, autonomous vehicles, or fleet units must coordinate effectively. Multi Agent Reinforcement Learning (MARL) offers a promising paradigm for addressing these challenges by enabling distributed agents to jointly learn optimal strategies that balance individual objectives with system wide efficiency. This paper presents a comprehensive survey of MARL applications in ITS. We introduce a structured taxonomy that categorizes MARL approaches according to coordination models and learning algorithms, spanning value based, policy based, actor critic, and communication enhanced frameworks. Applications are reviewed across key ITS domains, including traffic signal control, connected and autonomous vehicle coordination, logistics optimization, and mobility on demand systems. Furthermore, we highlight widely used simulation platforms such as SUMO, CARLA, and CityFlow that support MARL experimentation, along with emerging benchmarks. The survey also identifies core challenges, including scalability, non stationarity, credit assignment, communication constraints, and the sim to real transfer gap, which continue to hinder real world deployment."}]", "excerpt_truncated": true, "source_sha256": "b3fa7edd5edd6f202f444218d0496c95b737cf4cee310dbdeccce5abfc1186d1", "verification_required": true, "topic_domain": "emergent_preferences", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.3390/electronics12244963", "openalex:W4389543839", "arxiv:2508.20315"], "source_candidates": ["https://doi.org/10.3390/electronics12244963", "https://arxiv.org/pdf/2508.20315"], "source_candidate_identities": {}}
